/* 圓潤幼貓：固定圖案與星線對位，沿主星柔和分區揭露，完成後以光暈、輪廓及星塵同步呼吸。 */
const LYNX_ART='data:image/webp;base64,';
function lynxFig(W,H,p=1,aw,from){const n=++FIGN,q=Math.max(0,Math.min(1,p)),full=q===1,s=Math.min(W/380,H/300),tx=(W-380*s)/2,ty=(H-300*s)/2,
    prior=from==null?(aw&&full?5/6:q):Math.max(0,Math.min(1,from)),reveal=prior<q&&!reduce,fx=!reduce&&(aw||prior<q),d0=aw?.d0||0,delay=aw?d0+3.1:0,
    image='lynxImage'+n,rim='lynxRim'+n,aura='lynxAura'+n,mask='lynxMask'+n,clip='lynxClip'+n,sweep='lynxSweep'+n,bloom='lynxBloom'+n,region='lynxRegion'+n,lit=Math.round(q*6),before=Math.round(prior*6);
  return `<g class="cfx cfx-lynx${full?' full':''}${reveal?' revealing':''}${aw?' waking':''}" aria-hidden="true" transform="translate(${tx} ${ty}) scale(${s})" data-progress="${q}" style="--lynx-p:${q};--lynx-from:${prior};--lynx-rim:${.58*Math.pow(q,1.7)};--lynx-rim-from:${.58*Math.pow(prior,1.7)};--lynx-delay:${delay}s;--lynx-fx-delay:${d0}s">
    <defs>${lynxRegionMask(region,lit,reveal?before:lit,d0)}<clipPath id="${clip}"><rect width="380" height="300"/></clipPath>
    <filter id="${rim}" x="-10%" y="-10%" width="120%" height="120%" color-interpolation-filters="sRGB"><feGaussianBlur in="SourceAlpha" stdDeviation=".5" result="smooth"/><feComponentTransfer in="smooth" result="body"><feFuncA type="discrete" tableValues="0 0 0 0 0 0 1 1"/></feComponentTransfer><feMorphology in="body" operator="dilate" radius=".65" result="expanded"/><feComposite in="expanded" in2="body" operator="out" result="edge"/><feFlood flood-color="#BFFFEF" result="mint"/><feComposite in="mint" in2="edge" operator="in" result="rim"/><feGaussianBlur in="rim" stdDeviation=".85" result="halo"/><feMerge><feMergeNode in="halo"/><feMergeNode in="rim"/></feMerge></filter>
    <filter id="${aura}" x="-30%" y="-30%" width="160%" height="160%" color-interpolation-filters="sRGB"><feGaussianBlur in="SourceAlpha" stdDeviation=".6" result="smooth"/><feComponentTransfer in="smooth" result="body"><feFuncA type="discrete" tableValues="0 0 0 0 0 0 1 1"/></feComponentTransfer><feMorphology in="body" operator="dilate" radius="1.5" result="expanded"/><feGaussianBlur in="expanded" stdDeviation="5.5" result="wide"/><feGaussianBlur in="expanded" stdDeviation="1.8" result="near"/><feFlood flood-color="#83FFE3" result="mint"/><feComposite in="mint" in2="wide" operator="in" result="outer"/><feComposite in="mint" in2="near" operator="in" result="inner"/><feMerge><feMergeNode in="outer"/><feMergeNode in="inner"/></feMerge></filter>
    <mask id="${mask}" maskUnits="userSpaceOnUse" x="0" y="0" width="380" height="300" style="mask-type:alpha"><use href="#${image}"/></mask>
    <linearGradient id="${sweep}"><stop stop-color="#BFFFEF" stop-opacity="0"/><stop offset=".34" stop-color="#BFFFEF" stop-opacity=".15"/><stop offset=".52" stop-color="#F3FFF6" stop-opacity=".88"/><stop offset=".7" stop-color="#FFE7A3" stop-opacity=".28"/><stop offset="1" stop-color="#BFFFEF" stop-opacity="0"/></linearGradient>
    <radialGradient id="${bloom}"><stop stop-color="#BFFFEF" stop-opacity=".48"/><stop offset=".36" stop-color="#9C83FF" stop-opacity=".32"/><stop offset="1" stop-color="#9C83FF" stop-opacity="0"/></radialGradient></defs>
    <g clip-path="url(#${clip})">
    <use class="lynx-shadow" href="#${image}"/>
    <g class="lynx-regional" data-lit="${lit}" mask="url(#${region})">
    <g class="lynx-aura" opacity="0" filter="url(#${aura})"><use href="#${image}"/></g>
    ${aw&&!reduce?`<ellipse class="lynx-fx lynx-bloom" cx="206" cy="154" rx="168" ry="116" fill="url(#${bloom})"/>`:''}
    <g class="lynx-reveal" opacity="1"><g class="lynx-body"><image id="${image}" href="${LYNX_ART}" width="380" height="300" preserveAspectRatio="xMidYMid meet"/></g>${q?lynxTwinkles(mask):''}</g>
    <g class="lynx-rim" opacity="${.58*Math.pow(q,1.7)}" filter="url(#${rim})"><use href="#${image}"/></g>
    ${aw&&!reduce?`<g class="lynx-fx" mask="url(#${mask})"><g class="lynx-sweep"><rect x="-130" y="-100" width="105" height="520" fill="url(#${sweep})" transform="rotate(-18 190 150)"/></g></g>
    <g class="lynx-fx lynx-eyes">${[[280.9,98.3],[328.5,115.1]].map(([x,y],i)=>`<path class="lynx-glint" d="${sp4(x,y,2.65)}" fill="#F3FFFD" style="--glint-delay:${d0+.95+i*.14}s"/>`).join('')}</g>`:''}
    ${fx?lynxSparkFx(Math.max(1,Math.round(q*6)),n,d0,!!aw):''}</g></g></g>`}
/* 方案 A：依最近的已亮／未亮主星距離柔和分區；快取七個階段，不逐幀重畫。 */
const LYNX_REGIONS=new Map(),LYNX_STEPS=new Map();
function lynxMaskURL(values){const c=document.createElement('canvas');c.width=380;c.height=300;const x=c.getContext('2d'),d=x.createImageData(380,300);
  for(let i=0;i<values.length;i++){d.data[i*4]=d.data[i*4+1]=d.data[i*4+2]=255;d.data[i*4+3]=values[i]}x.putImageData(d,0,0);return c.toDataURL()}
function lynxRegion(lit){lit=Math.max(0,Math.min(6,Math.round(lit)));if(LYNX_REGIONS.has(lit))return LYNX_REGIONS.get(lit);
  const P=conProj('Lyn',380,300,46),ord=conOrd('Lyn'),values=new Uint8ClampedArray(380*300);
  if(lit===6)values.fill(255);else if(lit)for(let i=0;i<values.length;i++){const x=i%380,y=Math.floor(i/380);let a=Infinity,b=Infinity;
    ord.forEach((si,j)=>{const d=Math.hypot(x-P[si][0],y-P[si][1]);if(j<lit)a=Math.min(a,d);else b=Math.min(b,d)});
    const t=Math.max(0,Math.min(1,(b-a+24)/48));values[i]=255*t*t*(3-2*t)}
  const out={values,url:lynxMaskURL(values)};LYNX_REGIONS.set(lit,out);return out}
function lynxRegionStep(before,lit){const key=before+'-'+lit;if(LYNX_STEPS.has(key))return LYNX_STEPS.get(key);
  const a=lynxRegion(before).values,b=lynxRegion(lit).values,values=new Uint8ClampedArray(a.length),center=conProj('Lyn',380,300,46)[conOrd('Lyn')[lit-1]];let radius=1;
  for(let i=0;i<a.length;i++)if(b[i]>a[i]){values[i]=255*(b[i]-a[i])/(255-a[i]);radius=Math.max(radius,Math.hypot(i%380-center[0],Math.floor(i/380)-center[1]))}
  const out={url:lynxMaskURL(values),center,radius:Math.ceil(radius+24)};LYNX_STEPS.set(key,out);return out}
function lynxRegionMask(id,lit,before,d0){const frame='maskUnits="userSpaceOnUse" x="0" y="0" width="380" height="300" style="mask-type:alpha"',img=url=>`<image href="${url}" width="380" height="300"/>`;
  if(before>=lit)return `<mask id="${id}" ${frame}>${lit===6?'<rect width="380" height="300" fill="white"/>':img(lynxRegion(lit).url)}</mask>`;
  const step=lynxRegionStep(before,lit),wave=id+'Wave',gradient=id+'Gradient';
  return `<radialGradient id="${gradient}"><stop offset=".82" stop-color="white"/><stop offset="1" stop-color="white" stop-opacity="0"/></radialGradient>
    <mask id="${wave}" ${frame}><circle class="lynx-region-wave" cx="${step.center[0]}" cy="${step.center[1]}" r="${step.radius}" fill="url(#${gradient})" style="--region-radius:${step.radius}px;--region-delay:${d0}s"/></mask>
    <mask id="${id}" ${frame}>${img(lynxRegion(before).url)}<g mask="url(#${wave})">${img(step.url)}</g></mask>`}
/* 細小星塵位置固定、錯開閃爍；避開六顆主星，透明遮罩限制在幼貓身上。 */
function lynxTwinkles(mask){const points=[[73,146],[68,160],[104,163],[128,148],[154,151],[182,143],[209,132],[226,159],[199,174],[145,182],[110,197],[137,213],[183,217],[212,204],[243,188],[263,210],[168,254],[66,268],[88,285],[266,83],[292,67],[315,84],[340,91],[331,178]],P=conProj('Lyn',380,300,46),rng=seedRng('lynx-twinkles');
  return `<g class="lynx-twinkles" mask="url(#${mask})">${points.filter(([x,y])=>P.every(([px,py])=>Math.hypot(x-px,y-py)>9)).map(([x,y],i)=>{const r=.7+rng()*.35,d=2.2+rng()*1.4,delay=-rng()*3.6;
    return `<g class="lynx-twinkle" opacity=".2" fill="${i%3===0?'#FFF0CA':'#F0FFFC'}" style="--twinkle-duration:${d.toFixed(2)}s;--twinkle-delay:${delay.toFixed(2)}s"><path d="${sp4(x,y,r*2.1)}" opacity=".18"/><path d="${sp4(x,y,r*1.4)}"/></g>`}).join('')}</g>`}
function lynxSparkFx(count,n,d0,full){const P=conProj('Lyn',380,300,46),rng=seedRng('kitten-magic-'+count),B=P[count-1];let g='';
  if(count>1){const A=P[count-2];g+=`<path class="lynx-energy" d="M${A} L${B}" pathLength="1" fill="none" stroke="#F2FFF7" stroke-width="1.3" stroke-linecap="round"/>`}
  for(let j=0;j<(full?38:22);j++){const a=P[j%3===0?Math.floor(rng()*count):count-1],x=a[0]+(rng()-.5)*64,y=a[1]+(rng()-.5)*48,angle=rng()*Math.PI*2,d=42+rng()*64;
    g+=`<g class="lynx-gather" fill="${j%5===0?'#FFE7A3':'#BFFFEF'}" style="--sx:${Math.cos(angle)*d}px;--sy:${Math.sin(angle)*d}px;--particle-delay:${d0+j*.013}s">${j%4===0?`<path d="${sp4(x,y,.7+rng()*.75)}"/>`:`<circle cx="${x}" cy="${y}" r="${.4+rng()*.55}"/>`}</g>`}
  (full?P:[B]).forEach(([x,y],j)=>{g+=`<circle class="lynx-ring" cx="${x}" cy="${y}" r="${full?44:29}" fill="none" stroke="${j%2?'#FFE7A3':'#BFFFEF'}" stroke-width="1.2" style="--ring-delay:${d0+(full?.6+j*.075:0)}s"/>`});
  return `<g class="lynx-fx">${g}</g>`}
